content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Participant provides signed informed consent to participate in this study, which includes compliance with the requirements and restrictions listed in the Informed Consent Form and in this protocol.",
      "quote": "Participant provides signed informed consent (as described in Appendix 1) to participate in this study, which includes compliance with the requirements and restrictions listed in the Informed Consent Form and in this protocol."
    },
    {
      "kind": "inclusion",
      "text": "Participant must be age ≥18 years at the time of signing Informed Consent Form.",
      "quote": "Participant must be age ≥18 years at the time of signing Informed Consent Form.",
      "thresholds": [
        {"test": "age", "op": ">=", "value": 18, "unit": "years"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Participant has pathologically or cytologically confirmed, definitively diagnosed, locally advanced unresectable NSCLC (i.e., Stage IIIB not eligible for definitive chemoradiotherapy) or metastatic NSCLC (i.e., Stage IV), per the Union Internationale Contre le Cancer/American Joint Committee on Cancer staging system (Amin et al. 2017) of either squamous or non-squamous histology based on the major histologic component that has not been treated with systemic anticancer therapy for metastatic disease.",
      "quote": "Participant has pathologically or cytologically confirmed, definitively diagnosed, locally advanced unresectable NSCLC (i.e., Stage IIIB not eligible for definitive chemoradiotherapy) or metastatic NSCLC (i.e., Stage IV), per the Union Internationale Contre le Cancer/American Joint Committee on Cancer staging system (Amin et al. 2017) of either squamous or non-squamous histology based on the major histologic component that has not been treated with systemic anticancer therapy for metastatic disease."
    },
    {
      "kind": "inclusion",
      "text": "Participant has documented RET fusion that meets one of the following two criteria: Documented RET fusion using either tissue or plasma, as determined by an appropriate validated local test performed by a Clinical Laboratory Improvement Amendments (CLIA)-certified or equivalent accredited diagnostic laboratory. Or Documented RET fusion by a positive result from tumor tissue testing performed centrally by Foundation Medicine (FMI) clinical trial assay or an alternate, approved central laboratory for that region.",
      "quote": "Participant has documented RET fusion that meets one of the following two criteria: – Documented RET fusion using either tissue or plasma, as determined by an appropriate validated local test performed by a Clinical Laboratory Improvement Amendments (CLIA)-certified or equivalent accredited diagnostic laboratory. – Documented RET fusion by a positive result from tumor tissue testing performed centrally by Foundation Medicine (FMI) clinical trial assay or an alternate, approved central laboratory for that region."
    },
    {
      "kind": "inclusion",
      "text": "The participant agrees to provide preferably adequate tumor tissue (archived, if available, or a fresh biopsy) or if tumor tissue cannot be obtained, a fixed and embedded cell pellet from pleural effusion would be acceptable for central confirmation of RET fusion status using an NGS-based assay. If no adequate tumor material is available and a new biopsy is not feasible, the participant will not be eligible for enrollment. This specimen must be accompanied by the full laboratory report of the RET fusion local test and must also be submitted within 2 weeks of enrollment for confirmation of RET status by central testing.",
      "quote": "The participant agrees to provide preferably adequate tumor tissue (archived, if available, or a fresh biopsy) or if tumor tissue cannot be obtained, a fixed and embedded cell pellet from pleural effusion would be acceptable for central confirmation of RET fusion status using an NGS-based assay. If no adequate tumor material is available and a new biopsy is not feasible, the participant will not be eligible for enrollment. This specimen must be accompanied by the full laboratory report of the RET fusion local test and must also be submitted within 2 weeks of enrollment for confirmation of RET status by central testing."
    },
    {
      "kind": "inclusion",
      "text": "A representative formalin-fixed, paraffin-embedded (FFPE) tumor specimen in a paraffin block (preferred) or a target of 15-20 slides containing unstained, freshly cut, serial sections is required for participation in this study. A minimum of 10-14 slides is acceptable if the slides meet the tissue requirements in Section 8.10. Notify the Medical Monitor if less than 15 slides are available.",
      "quote": "A representative formalin-fixed, paraffin-embedded (FFPE) tumor specimen in a paraffin block (preferred) or a target of 15-20 slides containing unstained, freshly cut, serial sections is required for participation in this study. – A minimum of 10-14 slides is acceptable if the slides meet the tissue requirements in Section 8.10. Notify the Medical Monitor if less than 15 slides are available."
    },
    {
      "kind": "inclusion",
      "text": "Participant has an ECOG Performance Status 0 or 1 (see Appendix 7).",
      "quote": "Participant has an ECOG Performance Status 0 or 1 (see Appendix 7)."
    },
    {
      "kind": "inclusion",
      "text": "Participants who have a negative HIV test at screening, with the following exception: Individuals with a positive HIV test at screening are eligible, provided they are stable on anti-retroviral therapy, have a CD4 count ≥ 200/µL, and have an undetectable viral load.",
      "quote": "Participants who have a negative HIV test at screening, with the following exception: Individuals with a positive HIV test at screening are eligible, provided they are stable on anti-retroviral therapy, have a CD4 count ≥ 200/µL, and have an undetectable viral load.",
      "thresholds": [
        {"test": "CD4 count", "op": ">=", "value": 200, "unit": "/µL"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Participant has measurable disease, as determined by the local site investigator or radiologic assessment according to RECIST v1.1 (see Appendix 8). Lesions located in a previously irradiated area are considered measurable if progression has been demonstrated after irradiation.",
      "quote": "Participant has measurable disease, as determined by the local site investigator or radiologic assessment according to RECIST v1.1 (see Appendix 8). – Lesions located in a previously irradiated area are considered measurable if progression has been demonstrated after irradiation."
    },
    {
      "kind": "inclusion",
      "text": "Participant cannot have received any prior anticancer therapy for metastatic disease. Participants can have received previous anticancer therapy (except a selective RET inhibitor) in the neoadjuvant or adjuvant setting but must have experienced an interval of at least ≥6 months from completion of therapy to recurrence. Participants who have received previous immune checkpoint inhibitors in the adjuvant setting or consolidation therapy following chemoradiation are not allowed to receive pembrolizumab if randomized to Arm B.",
      "quote": "Participant cannot have received any prior anticancer therapy for metastatic disease. – Participants can have received previous anticancer therapy (except a selective RET inhibitor) in the neoadjuvant or adjuvant setting but must have experienced an interval of at least ≥6 months from completion of therapy to recurrence. – Participants who have received previous immune checkpoint inhibitors in the adjuvant setting or consolidation therapy following chemoradiation are not allowed to receive pembrolizumab if randomized to Arm B."
    },
    {
      "kind": "inclusion",
      "text": "Participant is an appropriate candidate for and agrees to receive one of the investigator choice platinum-based anticancer regimens if randomized to Arm B.",
      "quote": "Participant is an appropriate candidate for and agrees to receive one of the investigator choice platinum-based anticancer regimens if randomized to Arm B."
    },
    {
      "kind": "inclusion",
      "text": "For women of childbearing potential: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraception, as defined below: Women must remain abstinent or use a highly effective method of non-hormonal contraception with a failure rate of <1% per year during the treatment period and for a period of a minimum of 14 days after the final dose of pralsetinib. The duration of contraceptive methods for participants receiving SOC platinum-containing anticancer treatment regimens is as indicated in the respective applicable labeling documents (refer to Appendix 4, Section A4–1). A woman is considered to be of childbearing potential if she is postmenarchal, has not reached a postmenopausal state (i.e., ≥12 continuous months of amenorrhea with no identified cause other than menopause), and is not permanently infertile due to surgery (i.e., removal of ovaries, fallopian tubes, and/or uterus) or another cause, as determined by the investigator (e.g., Müllerian agenesis). The definition of childbearing potential may be adapted for alignment with local guidelines or regulations. Examples of contraceptive methods with a failure rate of <1% per year include bilateral tubal ligation, male partner sterilization, and copper intrauterine devices. The reliability of sexual abstinence should be evaluated in relation to the duration of the clinical trial and the preferred and usual lifestyle of the individual. Periodic abstinence (e.g., calendar, ovulation, symptothermal, or postovulation methods) and withdrawal are not adequate methods of contraception. If required per local guidelines or regulations, locally recognized adequate methods of contraception and information about the reliability of abstinence will be described in the local Informed Consent Form.",
      "quote": "For women of childbearing potential: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraception, as defined below: – Women must remain abstinent or use a highly effective method of non-hormonal contraception with a failure rate of <1% per year during the treatment period and for a period of a minimum of 14 days after the final dose of pralsetinib. The duration of contraceptive methods for participants receiving SOC platinum-containing anticancer treatment regimens is as indicated in the respective applicable labeling documents (refer to Appendix 4, Section A4–1). – A woman is considered to be of childbearing potential if she is postmenarchal, has not reached a postmenopausal state (i.e., ≥12 continuous months of amenorrhea with no identified cause other than menopause), and is not permanently infertile due to surgery (i.e., removal of ovaries, fallopian tubes, and/or uterus) or another cause, as determined by the investigator (e.g., Müllerian agenesis). The definition of childbearing potential may be adapted for alignment with local guidelines or regulations. – Examples of contraceptive methods with a failure rate of <1% per year include bilateral tubal ligation, male partner sterilization, and copper intrauterine devices. – The reliability of sexual abstinence should be evaluated in relation to the duration of the clinical trial and the preferred and usual lifestyle of the individual. Periodic abstinence (e.g., calendar, ovulation, symptothermal, or postovulation methods) and withdrawal are not adequate methods of contraception. If required per local guidelines or regulations, locally recognized adequate methods of contraception and information about the reliability of abstinence will be described in the local Informed Consent Form."
    },
    {
      "kind": "inclusion",
      "text": "For men: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraceptive methods, and agree to refrain from donating sperm, as defined below: With a female partner of childbearing potential who is not pregnant, men who are not surgically sterile must remain abstinent or use a condom plus an additional contraceptive method that together result in a failure rate of < 1% per year, during the treatment period and for 7 days after the final dose of pralsetinib to avoid exposing the embryo. With pregnant female partners, men must remain abstinent or use a condom during the treatment period and for at least 7 days after the final dose of pralsetinib to avoid exposing the embryo. Men must refrain from donating sperm during this same period. The duration of contraceptive methods for participants receiving investigator’s choice of SOC platinum-containing anticancer treatment is as indicated in the respective applicable labeling documents (refer to Appendix 4, Section A4–2). The reliability of sexual abstinence should be evaluated in relation to the duration of the clinical trial and the preferred and usual lifestyle of the individual. Periodic abstinence and withdrawal are not adequate methods of preventing drug exposure. If required per local guidelines or regulations, information about the reliability of abstinence will be described in the local Informed Consent Form.",
      "quote": "For men: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraceptive methods, and agree to refrain from donating sperm, as defined below: – With a female partner of childbearing potential who is not pregnant, men who are not surgically sterile must remain abstinent or use a condom plus an additional contraceptive method that together result in a failure rate of < 1% per year, during the treatment period and for 7 days after the final dose of pralsetinib to avoid exposing the embryo. With pregnant female partners, men must remain abstinent or use a condom during the treatment period and for at least 7 days after the final dose of pralsetinib to avoid exposing the embryo. Men must refrain from donating sperm during this same period. The duration of contraceptive methods for participants receiving investigator’s choice of SOC platinum-containing anticancer treatment is as indicated in the respective applicable labeling documents (refer to Appendix 4, Section A4–2). – The reliability of sexual abstinence should be evaluated in relation to the duration of the clinical trial and the preferred and usual lifestyle of the individual. Periodic abstinence and withdrawal are not adequate methods of preventing drug exposure. If required per local guidelines or regulations, information about the reliability of abstinence will be described in the local Informed Consent Form."
    },
    {
      "kind": "exclusion",
      "text": "Participant’s tumor has any additional known primary driver alterations other than RET, such as targetable mutations of EGFR, ALK, ROS1, MET, and BRAF. Investigators should inform the Medical Monitor about the enrollment of participants with tumors having comutations.",
      "quote": "Participant’s tumor has any additional known primary driver alterations other than RET, such as targetable mutations of EGFR, ALK, ROS1, MET, and BRAF. Investigators should inform the Medical Monitor about the enrollment of participants with tumors having comutations."
    },
    {
      "kind": "exclusion",
      "text": "Participant previously received treatment with a selective RET inhibitor.",
      "quote": "Participant previously received treatment with a selective RET inhibitor."
    },
    {
      "kind": "exclusion",
      "text": "Participant received radiotherapy or radiosurgery to any site within 14 days before randomization or more than 30 Gy of radiotherapy to the lung in the 6 months before randomization.",
      "quote": "Participant received radiotherapy or radiosurgery to any site within 14 days before randomization or more than 30 Gy of radiotherapy to the lung in the 6 months before randomization."
    },
    {
      "kind": "exclusion",
      "text": "Participants with a history of pneumonitis of non-infectious etiology within the last 12 months.",
      "quote": "Participants with a history of pneumonitis of non-infectious etiology within the last 12 months."
    },
    {
      "kind": "exclusion",
      "text": "Participants with autoimmune disease that requires systemic therapy (excluding thyroid, vitiligo).",
      "quote": "Participants with autoimmune disease that requires systemic therapy (excluding thyroid, vitiligo)."
    },
    {
      "kind": "exclusion",
      "text": "Participants with autoimmune disease within 2 years of study enrollment are not eligible for the pembrolizumab-containing regimen.",
      "quote": "Participants with autoimmune disease within 2 years of study enrollment are not eligible for the pembrolizumab-containing regimen."
    },
    {
      "kind": "exclusion",
      "text": "Participants with a medical condition that requires immunosuppression.",
      "quote": "Participants with a medical condition that requires immunosuppression."
    },
    {
      "kind": "exclusion",
      "text": "Participant has either CNS metastases or a primary CNS tumor that is associated with progressive neurological symptoms or requires increasing doses of corticosteroids to control the CNS disease. If a participant requires corticosteroids for management of CNS disease, the dose must be stable for the 2 weeks prior to Day 1 of Cycle 1.",
      "quote": "Participant has either CNS metastases or a primary CNS tumor that is associated with progressive neurological symptoms or requires increasing doses of corticosteroids to control the CNS disease. – If a participant requires corticosteroids for management of CNS disease, the dose must be stable for the 2 weeks prior to Day 1 of Cycle 1."
    },
    {
      "kind": "exclusion",
      "text": "Participant has significant cardiovascular disease, as evidenced by any of the following conditions: Participant has a QT interval corrected through the use of Fridericia’s formula (QTcF) >480 ms. Participant has a history of prolonged QT syndrome or torsades de pointes. Participant has a familial history of prolonged QT syndrome. Participant has clinically significant, uncontrolled, cardiovascular disease, including Grade III or IV congestive heart failure according to the New York Heart Association (NYHA) classification; myocardial infarction or unstable angina within the previous 6 months, uncontrolled hypertension, or clinically significant, uncontrolled arrhythmias, including bradyarrhythmias that may cause QT prolongation (e.g., Type II second-degree or third-degree heart block).",
      "quote": "Participant has significant cardiovascular disease, as evidenced by any of the following conditions: – Participant has a QT interval corrected through the use of Fridericia’s formula (QTcF) >480 ms. – Participant has a history of prolonged QT syndrome or torsades de pointes. – Participant has a familial history of prolonged QT syndrome. – Participant has clinically significant, uncontrolled, cardiovascular disease, including Grade III or IV congestive heart failure according to the New York Heart Association (NYHA) classification; myocardial infarction or unstable angina within the previous 6 months, uncontrolled hypertension, or clinically significant, uncontrolled arrhythmias, including bradyarrhythmias that may cause QT prolongation (e.g., Type II second-degree or third-degree heart block).",
      "thresholds": [
        {"test": "QTcF", "op": ">", "value": 480, "unit": "ms"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Participant requires treatment with a prohibited medication or herbal remedy (as specified in Section 6.8.3) that cannot be discontinued at least 2 weeks prior to the start of study drug administration. Pralsetinib may be started within 14 days of stopping a prohibited medication if considered by the investigator to be safe and in the best interest of the participant. Inform the medical monitor if you are considering administering pralsetinib within 14 days of stopping a prohibited medication.",
      "quote": "Participant requires treatment with a prohibited medication or herbal remedy (as specified in Section 6.8.3) that cannot be discontinued at least 2 weeks prior to the start of study drug administration. – Pralsetinib may be started within 14 days of stopping a prohibited medication if considered by the investigator to be safe and in the best interest of the participant. Inform the medical monitor if you are considering administering pralsetinib within 14 days of stopping a prohibited medication."
    },
    {
      "kind": "exclusion",
      "text": "Participant received treatment with hematopoietic growth factor support within 14 days of the first dose of study drug.",
      "quote": "Participant received treatment with hematopoietic growth factor support within 14 days of the first dose of study drug."
    },
    {
      "kind": "exclusion",
      "text": "Participant has had a major surgical procedure within 14 days of the first dose of study drug or is planned to have such procedure during the study period. Procedures, such as central venous catheter placement, tumor needle biopsy, and feeding tube placement, are not considered major surgical procedures.",
      "quote": "Participant has had a major surgical procedure within 14 days of the first dose of study drug or is planned to have such procedure during the study period. – Procedures, such as central venous catheter placement, tumor needle biopsy, and feeding tube placement, are not considered major surgical procedures."
    },
    {
      "kind": "exclusion",
      "text": "Participant has had a history of another primary malignancy that has been diagnosed or required therapy within the past 3 years prior to randomization. The following prior malignancies are not exclusionary: completely resected basal cell and squamous cell skin cancer, curatively treated localized prostate cancer, curatively treated localized thyroid cancer, and completely resected carcinoma in situ of any site.",
      "quote": "Participant has had a history of another primary malignancy that has been diagnosed or required therapy within the past 3 years prior to randomization. – The following prior malignancies are not exclusionary: completely resected basal cell and squamous cell skin cancer, curatively treated localized prostate cancer, curatively treated localized thyroid cancer, and completely resected carcinoma in situ of any site."
    },
    {
      "kind": "exclusion",
      "text": "Participant has any of the following within 14 days prior to the first dose of study drug: Platelet count <75×10^9/L; ANC <1.0×10^9/L; Hemoglobin <9.0 g/dL; AST or ALT >3×ULN if no hepatic metastases are present; >5×ULN if hepatic metastases are present; Total bilirubin >1.5×ULN; >3×ULN in presence of Gilbert disease; Estimated (according to the Cockcroft-Gault formula) or measured creatinine clearance <45 mL/min; Total serum phosphorous >5.5 mg/dL.",
      "quote": "Participant has any of the following within 14 days prior to the first dose of study drug: – Platelet count <75×109/L – ANC <1.0×109/L – Hemoglobin <9.0 g/dL RBC transfusion and erythropoietin may be used to reach at least 9.0 g/dL but must have been administered at least 2 weeks before the first dose of study drug. – AST or ALT >3×the upper limit of normal (ULN) if no hepatic metastases are present; >5×ULN if hepatic metastases are present – Total bilirubin >1.5×ULN; >3×ULN in presence of Gilbert disease – Estimated (according to the Cockcroft-Gault formula) or measured creatinine clearance <45 mL/min – Total serum phosphorous >5.5 mg/dL",
      "thresholds": [
        {"test": "Platelet count", "op": "<", "value": 75, "unit": "10^9/L"},
        {"test": "ANC", "op": "<", "value": 1.0, "unit": "10^9/L"},
        {"test": "Hemoglobin", "op": "<", "value": 9.0, "unit": "g/dL"},
        {"test": "AST", "op": ">", "value": 3, "unit": "xULN"},
        {"test": "ALT", "op": ">", "value": 3, "unit": "xULN"},
        {"test": "AST", "op": ">", "value": 5, "unit": "xULN"},
        {"test": "ALT", "op": ">", "value": 5, "unit": "xULN"},
        {"test": "Total bilirubin", "op": ">", "value": 1.5, "unit": "xULN"},
        {"test": "Total bilirubin", "op": ">", "value": 3, "unit": "xULN"},
        {"test": "Creatinine clearance", "op": "<", "value": 45, "unit": "mL/min"},
        {"test": "Total serum phosphorous", "op": ">", "value": 5.5, "unit": "mg/dL"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Participant has a known hypersensitivity to cisplatin, carboplatin, pemetrexed, or pembrolizumab (for participants with NSCLC of non-squamous histology only), or carboplatin, gemcitabine, pembrolizumab, paclitaxel, or nab-paclitaxel (for participants with NSCLC of squamous histology only).",
      "quote": "Participant has a known hypersensitivity to cisplatin, carboplatin, pemetrexed, or pembrolizumab (for participants with NSCLC of non-squamous histology only), or carboplatin, gemcitabine, pembrolizumab, paclitaxel, or nab-paclitaxel (for participants with NSCLC of squamous histology only)."
    },
    {
      "kind": "exclusion",
      "text": "Participant with a serious infection requiring systemic antibiotics within 7 days prior to initiation of study treatment, or any active infection that, in the opinion of the investigator, could impact patient's safety. In the setting of a pandemic or epidemic, screening for active infections should be considered according to local or institutional guidelines or guidelines of applicable professional societies (e.g., ASCO or ESMO).",
      "quote": "Participant with a serious infection requiring systemic antibiotics within 7 days prior to initiation of study treatment, or any active infection that, in the opinion of the investigator, could impact patient's safety. – In the setting of a pandemic or epidemic, screening for active infections should be considered according to local or institutional guidelines or guidelines of applicable professional societies (e.g., ASCO or ESMO)."
    },
    {
      "kind": "exclusion",
      "text": "Participant has an active, uncontrolled infection (viral, bacterial, or fungal). Participants with controlled infections who are stable on treatment may be eligible if the benefit-risk assessment is justified, and permission is granted from the Sponsor.",
      "quote": "Participant has an active, uncontrolled infection (viral, bacterial, or fungal). – Participants with controlled infections who are stable on treatment may be eligible if the benefit-risk assessment is justified, and permission is granted from the Sponsor."
    },
    {
      "kind": "exclusion",
      "text": "Participant has positive hepatitis C virus (HCV) antibody test at screening. Participants positive for HCV antibody are eligible only if PCR is negative for HCV RNA.",
      "quote": "Participant has positive hepatitis C virus (HCV) antibody test at screening. – Participants positive for HCV antibody are eligible only if PCR is negative for HCV RNA."
    },
    {
      "kind": "exclusion",
      "text": "Participant has positive hepatitis B surface antigen (HBsAg) test at screening. Participants with a previous hepatitis B virus (HBV) infection or resolved HBV infection (hepatitis B core antibody [HBcAb] positive, but negative HBsAg) are eligible only if the HBV DNA test is negative.",
      "quote": "Participant has positive hepatitis B surface antigen (HBsAg) test at screening. – Participants with a previous hepatitis B virus (HBV) infection or resolved HBV infection (hepatitis B core antibody [HBcAb] positive, but negative HBsAg) are eligible only if the HBV DNA test is negative."
    },
    {
      "kind": "exclusion",
      "text": "Participant is unwilling or unable to comply with scheduled visits, study drug administration plan (including the inability or unwillingness to swallow capsules), laboratory tests, or other study procedures and study restrictions.",
      "quote": "Participant is unwilling or unable to comply with scheduled visits, study drug administration plan (including the inability or unwillingness to swallow capsules), laboratory tests, or other study procedures and study restrictions."
    },
    {
      "kind": "exclusion",
      "text": "Participant is pregnant, as documented by a serum β-human chorionic gonadotropin (βhCG) pregnancy test consistent with pregnancy obtained within 7 days before the",
      "quote": "Participant is pregnant, as documented by a serum β-human chorionic gonadotropin (βhCG) pregnancy test consistent with pregnancy obtained within 7 days before the"
    }
  ]
}
